  static boolean waveWindow(GameState s, Params p) {
    if (p.WAVE_FRONT_TURN > 0 && s.turn >= p.WAVE_FRONT_TURN) return false;
    for (int i = 0; i < s.nSites; i++) if (s.stOwner[i] == 1 && s.stType[i] == Const.BARRACKS && s.barrType[i] == Const.KNIGHT) return true;
