  static double depth(double x, double hx) { return Math.abs(x - hx); }
  private static int nearestBack(GameState s, double cx, double cy, double hx, int front, IntPredicate ok) {
    if (front > 0) { int t = nearest(s, cx, cy, i -> ok.test(i) && depth(s.sx[i], hx) <= front); if (t >= 0) return t; }
    return nearest(s, cx, cy, ok); }

